def bergman_membership(weights: Sequence[float], circuits: Sequence[Circuit]) -> bool:
    """Return whether every circuit has at least two exact minimizers."""
    for circuit in circuits:
        if not circuit:
            raise ValueError("Circuits must be nonempty")
        least = min(weights[e] for e in circuit)
        if sum(weights[e] == least for e in circuit) < 2:
            return False
    return True

from __future__ import annotations
from typing import Sequence

Circuit = tuple[int, ...]

def circuit_components(size: int, circuits: Sequence[Circuit]) -> list[list[int]]:
    """Compute classes generated by common-circuit adjacency."""
    parent = list(range(size))
    rank = [0] * size
    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x: int, y: int) -> None:
        x, y = find(x), find(y)
        if x == y:
            return
        if rank[x] < rank[y]:
            x, y = y, x
        parent[y] = x
        if rank[x] == rank[y]:
            rank[x] += 1
    for circuit in circuits:
        if not circuit:
            raise ValueError("Circuits must be nonempty")
        for element in circuit[1:]:
            union(circuit[0], element)
    groups: dict[int, list[int]] = {}
    for element in range(size):
        groups.setdefault(find(element), []).append(element)
    return list(groups.values())

